sys_script_include.script:
// Role: the compliance team's decisions. Approving makes the proof count until its expiry date, freezes the scope
//       and seals the record; rejecting sends the owner back with a reason. Both tell the owner by email.
//       Both return '' on success, or an error message.
var CPMReview = Class.create();
CPMReview.prototype = {
  APPROVED_EVENT: 'x_1929776_compli_0.evidence.approved',
  REJECTED_EVENT: 'x_1929776_compli_0.evidence.rejected',

  initialize: function() {
    this.util = new CPMUtil();
  },

  // Role: approves a pending submission and starts the clock on the control's validity period.
  approve: function(evidenceId) {
    var loaded = this._load(evidenceId);
    if (loaded.error) return loaded.error;

    var days = parseInt(loaded.mapping.control.validity_days + '', 10) || 365;
    var until = this.util.addDays(this.util.today(), days);
    this._supersedeOlder(loaded.mapping.getUniqueValue(), evidenceId);

    var evidence = loaded.evidence;
    evidence.setValue('status', 'approved');
    evidence.setValue('valid_until', until);
    evidence.setValue('scope_snapshot', this._snapshot(loaded.mapping));   // what the service was made of today
    this._stamp(evidence);
    evidence.setValue('seal', this.seal(evidence));                         // detects any later change
    evidence.update();

    loaded.mapping.setValue('state', 'approved');
    loaded.mapping.setValue('valid_until', until);
    loaded.mapping.update();

    this._notify(this.APPROVED_EVENT, evidence, loaded.mapping);
    return '';
  },

  // Role: rejects a pending submission. A comment is required, because the owner receives it by email.
  reject: function(evidenceId, comment) {
    var loaded = this._load(evidenceId);
    if (loaded.error) return loaded.error;
    comment = (comment || '').trim();
    if (!comment) return 'Write a short reason before rejecting: the owner will read it.';

    var evidence = loaded.evidence;
    evidence.setValue('status', 'rejected');
    evidence.setValue('review_comment', comment.substring(0, 500));
    this._stamp(evidence);
    evidence.update();

    // A rejected first submission sends the control back to the owner. A rejected renewal does not:
    // the older approved proof keeps counting until it expires.
    if (loaded.mapping.getValue('state') == 'awaiting') {
      loaded.mapping.setValue('state', 'rejected');
      loaded.mapping.update();
    }
    this._notify(this.REJECTED_EVENT, evidence, loaded.mapping);
    return '';
  },

  // Role: the integrity seal: a SHA-256 fingerprint of the facts of the approval and of every file.
  //       The state is left out, so a later move to Superseded does not break it. Returns '' if hashing is unavailable.
  seal: function(evidence) {
    try {
      var parts = [
        evidence.getValue('number'), evidence.getValue('mapping'), evidence.getValue('valid_until'),
        evidence.getValue('submitted_by'), evidence.getValue('submitted_on'),
        evidence.getValue('reviewed_by'), evidence.getValue('reviewed_on'), evidence.getValue('scope_snapshot')
      ];
      var files = [];
      var att = new GlideSysAttachment().getAttachments('x_1929776_compli_0_evidence', evidence.getUniqueValue());
      while (att.next()) files.push(att.getValue('file_name') + ':' + att.getValue('size_bytes') + ':' + (att.getValue('hash') || ''));
      files.sort();
      return new GlideDigest().getSHA256Hex(parts.concat(files).join('|'));
    } catch (e) {
      gs.warn('[CPM] seal unavailable: ' + e.message);
      return '';
    }
  },

  // Role: compares the stored seal with a fresh one. Returns 'ok', 'changed', or 'none' when the record has no seal.
  verify: function(evidence) {
    var stored = evidence.getValue('seal');
    if (!stored) return 'none';
    return stored == this.seal(evidence) ? 'ok' : 'changed';
  },

  // Role: tells the person who submitted the evidence (or the owner of the control) about the decision.
  _notify: function(eventName, evidence, mapping) {
    var recipient = evidence.getValue('submitted_by') || mapping.getValue('owner');
    if (recipient) gs.eventQueue(eventName, evidence, recipient, '');
  },

  // Role: the list of components of the CI today, frozen into the evidence. A failure here never blocks an approval.
  _snapshot: function(mapping) {
    try {
      return new CPMScope().snapshot(mapping.getValue('target'));
    } catch (e) {
      gs.warn('[CPM] scope snapshot unavailable: ' + e.message);
      return '';
    }
  },

  // Role: loads the submission and its mapping, and refuses anything the reviewer must not do.
  _load: function(evidenceId) {
    if (!gs.hasRole('x_1929776_compli_0.admin')) return { error: 'Only the compliance team can review evidence.' };
    var evidence = new GlideRecord('x_1929776_compli_0_evidence');
    if (!evidenceId || !evidence.get(evidenceId) || evidence.getValue('status') != 'pending')
      return { error: 'This evidence is no longer waiting for review.' };
    if (evidence.getValue('submitted_by') == gs.getUserID() && this.util.prop('allow_self_review', 'false') != 'true')
      return { error: 'You cannot review evidence that you submitted yourself.' };
    var mapping = new GlideRecord('x_1929776_compli_0_mapping');
    if (!mapping.get(evidence.getValue('mapping'))) return { error: 'The control assignment no longer exists.' };
    return { evidence: evidence, mapping: mapping };
  },

  // Role: records who decided and when. The caller saves the record.
  _stamp: function(evidence) {
    evidence.setValue('reviewed_by', gs.getUserID());
    evidence.setValue('reviewed_on', new GlideDateTime().getValue());
  },

  // Role: when a new proof is approved, earlier approved proofs of the same control are marked Superseded.
  _supersedeOlder: function(mappingId, exceptId) {
    var older = new GlideRecord('x_1929776_compli_0_evidence');
    older.addQuery('mapping', mappingId);
    older.addQuery('status', 'approved');
    older.addQuery('sys_id', '!=', exceptId);
    older.query();
    while (older.next()) {
      older.setValue('status', 'superseded');
      older.update();
    }
  },

  type: 'CPMReview'
};
